const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const lakeWinnipeg = ee.Geometry.Rectangle([-99.4, 50.3, -95.9, 53.9]);
    const date1_start = '2021-05-06';
    const date1_end = '2021-05-08';
    const date2_start = '2021-05-18';
    const date2_end = '2021-05-20';

    // 2. Data Acquisition & Processing Function
    const getIceExtent = function(startDate, endDate) {
        // Function to mask clouds using the Sentinel-2 QA band.
        const maskS2clouds = function(image) {
            const qa = image.select('QA60');
            // Bits 10 and 11 are clouds and cirrus, respectively.
            const cloudBitMask = 1 << 10;
            const cirrusBitMask = 1 << 11;
            // Both flags should be set to zero, indicating clear conditions.
            const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
            return image.updateMask(mask).divide(10000)
                .copyProperties(image, ["system:time_start"]);
        };

        let collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
            .filterBounds(lakeWinnipeg)
            .filterDate(startDate, endDate);

        // Use Landsat 8 as a fallback if Sentinel-2 is empty
        if (collection.size().getInfo() === 0) {
            collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
                .filterBounds(lakeWinnipeg)
                .filterDate(startDate, endDate);

            // If fallback also fails
            if (collection.size().getInfo() === 0) return {collectionSize: 0, image: null};
        }

        let image = collection.map(maskS2clouds).mosaic();

        // Calculate NDSI = (Green - SWIR1) / (Green + SWIR1)
        // Sentinel-2: B3 (Green), B11 (SWIR1)
        // Landsat 8: B3 (Green), B6 (SWIR1)
        let ndsi;
        const s2_bands = ee.List(['B3', 'B11']);
        const l8_bands = ee.List(['SR_B3', 'SR_B6']);

        // Dynamically select bands based on collection ID
        const collectionId = collection.first().get('system:id').getInfo();
        if (collectionId.includes('COPERNICUS')) {
             ndsi = image.normalizedDifference(s2_bands).rename('ndsi');
        } else {
             ndsi = image.select(l8_bands, ['Green', 'SWIR1']).normalizedDifference(['Green', 'SWIR1']).rename('ndsi');
        }

        // Ice is where NDSI > 0.4
        const ice = ndsi.gt(0.4);
        return {collectionSize: collection.size().getInfo(), image: ice};
    };

    // 3. Calculation for both dates
    const result1 = getIceExtent(date1_start, date1_end);
    const result2 = getIceExtent(date2_start, date2_end);

    console.log(`Images found for May 7, 2021 period: ${result1.collectionSize}`);
    console.log(`Images found for May 19, 2021 period: ${result2.collectionSize}`);

    if (result1.collectionSize === 0 || result2.collectionSize === 0) {
        console.log("Evidence: No cloud-free images were found for one or both dates.");
        console.log("A");
        return;
    }

    const scale = 3000;
    const commonReducer = ee.Reducer.sum().unweighted();

    const stats1 = result1.image.reduceRegion({
        reducer: commonReducer,
        geometry: lakeWinnipeg,
        scale: scale,
        maxPixels: 1e9
    });

    const stats2 = result2.image.reduceRegion({
        reducer: commonReducer,
        geometry: lakeWinnipeg,
        scale: scale,
        maxPixels: 1e9
    });

    const icePixels1 = stats1.get('ndsi').getInfo();
    const icePixels2 = stats2.get('ndsi').getInfo();

    if (icePixels1 === null || icePixels2 === null) {
        console.log("Evidence: Calculation failed, could not retrieve pixel counts.");
        console.log("C3");
        return;
    }

    if (icePixels1 === 0 && icePixels2 === 0) {
        console.log("Evidence: No valid pixels (ice or water) found after cloud masking.");
        console.log("C2");
        return;
    }

    const iceArea1 = icePixels1 * Math.pow(scale, 2) / 1e6; // km^2
    const iceArea2 = icePixels2 * Math.pow(scale, 2) / 1e6; // km^2

    console.log(`Evidence: Estimated ice extent on May 7, 2021: ${iceArea1.toLocaleString('en-US', {maximumFractionDigits: 0})} km^2`);
    console.log(`Evidence: Estimated ice extent on May 19, 2021: ${iceArea2.toLocaleString('en-US', {maximumFractionDigits: 0})} km^2`);

    if (iceArea2 < iceArea1) {
        console.log("A");
    } else {
        console.log("B");
    }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
  process.stderr.write(`An error occurred: ${err}\n`);
  console.log("D");
});
